//! B-010a: the transcode acceptance gate — env-gated, disposable trees
//! only (`deltas/b010a_plan.md` §3.4).
//!
//! Env: `RUFIN_LIBGPOD_DIR` (the pinned libgpod install). No snapshot
//! corpus is touched: the device tree is built fresh by
//! `ipod::testkit::init_device`, and the source audio is generated by the
//! test itself. The chain under test is exactly the one the B-010 executor
//! will call: decide → encode → gated create/copy/write → re-parse.

use std::path::Path;

use ipod_sync::sync::transcode::{FileWriteMode, TRANSCODE_TARGET_KBPS, decide_file_write};

/// Convert a device colon-form path (`:iPod_Control:Music:F00:ABCD.m4a`)
/// into the filesystem path under the mount.
fn colon_to_path(mount: &Path, ipod_path: &str) -> std::path::PathBuf {
    mount.join(ipod_path.trim_start_matches(':').replace(':', "/"))
}

/// A 1-second 44.1 kHz stereo 16-bit silence WAV — nominal 1411 kbps, the
/// record shape that triggers the transcode rule.
fn write_wide_wave(path: &Path) {
    let sample_rate = 44_100_u32;
    let channels = 2_u32;
    let bits = 16_u32;
    let block_align = channels * bits / 8;
    let byte_rate = sample_rate * block_align;
    let data_size = byte_rate; // exactly 1 second
    let mut file = std::fs::File::create(path).unwrap();
    use std::io::Write;
    file.write_all(b"RIFF").unwrap();
    file.write_all(&(36 + data_size).to_le_bytes()).unwrap();
    file.write_all(b"WAVEfmt ").unwrap();
    file.write_all(&16_u32.to_le_bytes()).unwrap();
    file.write_all(&1_u16.to_le_bytes()).unwrap();
    file.write_all(&(channels as u16).to_le_bytes()).unwrap();
    file.write_all(&sample_rate.to_le_bytes()).unwrap();
    file.write_all(&byte_rate.to_le_bytes()).unwrap();
    file.write_all(&(block_align as u16).to_le_bytes()).unwrap();
    file.write_all(&(bits as u16).to_le_bytes()).unwrap();
    file.write_all(b"data").unwrap();
    file.write_all(&data_size.to_le_bytes()).unwrap();
    file.write_all(&vec![0_u8; data_size as usize]).unwrap();
}

#[test]
fn transcode_chain_gate() {
    let Ok(backend) = ipod::IpodBackend::load() else {
        eprintln!(
            "skipping: backend unavailable (see scripts/build-libgpod.sh and \
             export RUFIN_LIBGPOD_DIR)"
        );
        return;
    };
    let workdir = tempfile::tempdir().unwrap();
    let device_root = workdir.path().join("device");
    ipod::testkit::init_device(&backend, &device_root, "MA446", "fixture-pod").unwrap();
    ipod::testkit::seed_sysinfo(&device_root, "MA446").unwrap();

    // The pure decision matrix — the owner rule arms, no backend involved.
    assert_eq!(
        decide_file_write(Some("wav"), Some(1411)).mode,
        FileWriteMode::TranscodeToAac256
    );
    assert_eq!(
        decide_file_write(Some("mp3"), Some(320)).mode,
        FileWriteMode::CopyVerbatim
    );
    assert_eq!(
        decide_file_write(Some("m4a"), Some(256)).mode,
        FileWriteMode::CopyVerbatim
    );
    assert_eq!(
        decide_file_write(Some("pdf"), Some(64)).mode,
        FileWriteMode::NeverCopy
    );

    // A high-nominal-bitrate source triggers the transcode arm, then the
    // B-010a encoder produces the m4a the pod wants.
    let source = workdir.path().join("source.wav");
    write_wide_wave(&source);
    let encoded = workdir.path().join("encoded.m4a");
    let uri = gstreamer::glib::filename_to_uri(&source, None).unwrap();
    audio_processing::transcode_to_m4a(
        &audio_processing::ResolvedStream::new(uri.as_str()),
        TRANSCODE_TARGET_KBPS,
        &encoded,
        || false,
    )
    .unwrap();
    let encoded_bytes = std::fs::read(&encoded).unwrap();
    assert!(encoded_bytes.len() > 100, "non-trivial encoded size");
    // The B-009 capacity formula's conservative upper bound
    // (32000 bytes/s of audio, 1 s here) must hold.
    assert!(
        encoded_bytes.len() <= 32000 + 16 * 1024,
        "encoded size {} exceeds the conservative bound",
        encoded_bytes.len()
    );

    // Copy the encoded file onto the disposable device tree through the
    // gated wrapper surface (the sync-writes dev-dependency), exactly like
    // the executor will.
    let mut session = ipod::DeviceSession::open(&backend, &device_root).unwrap();
    let dbid = session
        .create_track(&ipod::TrackMetadata {
            title: Some("Транскодированный".to_string()),
            filetype: Some("m4a".to_string()),
            size: Some(encoded_bytes.len() as u32),
            tracklen: Some(1000),
            bitrate: Some(TRANSCODE_TARGET_KBPS as i32),
            samplerate: Some(48000),
            ..Default::default()
        })
        .unwrap();
    session.copy_track(dbid, &encoded).unwrap();
    session.write_library().unwrap();
    drop(session);

    // Re-parse: the written database must describe the copied file.
    let session = ipod::DeviceSession::open(&backend, &device_root).unwrap();
    let tracks = session.tracks().unwrap();
    assert_eq!(tracks.len(), 1);
    let track = &tracks[0];
    assert_eq!(track.dbid, dbid, "dbid stable across the write");
    assert_eq!(track.filetype.as_deref(), Some("m4a"));
    assert_eq!(track.bitrate, TRANSCODE_TARGET_KBPS as i32);
    let ipod_path = track
        .ipod_path
        .as_deref()
        .expect("copy_track must record the on-pod path");
    assert!(
        ipod_path.ends_with(".m4a"),
        "the on-pod path keeps the m4a type: {ipod_path:?}"
    );
    let on_disk = colon_to_path(&device_root, ipod_path);
    assert_eq!(
        std::fs::read(&on_disk).unwrap(),
        encoded_bytes,
        "the copied bytes are exactly the encoded m4a"
    );
}
